css:
.print-format table,
.print-format tr,
.print-format td,
.print-format div,
.print-format p {
	line-height: 150%;
	vertical-align: middle;
	font-family: Monospace;.print-format {
	font-family: Monospace;
	font-size: 12px;
	padding: 20px 24px !important;
	line-height: 1.6;
}

.print-format table,
.print-format tr,
.print-format td,
.print-format th,
.print-format div,
.print-format p {
	line-height: 160%;
	vertical-align: middle;
}

.print-format .table td,
.print-format .table th {
	padding: 8px 10px;
}

@media screen {
	.print-format {
		width: 7.5in;
		min-height: 8in;
		margin: auto;
	}
}
}

@media screen {
	.print-format {
		width: 5.5in;
		padding: 0.25in;
		min-height: 8in;
	}
}
